package local.remote;
import java.util.*;import java.nio.file.*;import com.google.gson.*;
import net.minecraft.client.Minecraft;import net.minecraft.network.protocol.game.ServerboundMovePlayerPacket;import net.minecraft.world.phys.Vec3;
import net.neoforged.api.distmarker.Dist;import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.client.event.ClientTickEvent;
@Mod(value="remote_spatial_client",dist=Dist.CLIENT) public class RemoteClientProbe {
 final Path dir=Path.of("../exchange");final List<String> lines=new ArrayList<>();final List<Runnable> tasks=new ArrayList<>();String pending;JsonObject response;int tick,at,index,waitUntil;boolean done;double wantedX;int walkTicks;
 void check(boolean ok,String text){lines.add((ok?"PASS ":"FAIL ")+text);}
 void request(String op,Object...pairs){try{var q=new JsonObject();q.addProperty("op",op);for(int i=0;i<pairs.length;i+=2){Object v=pairs[i+1];String k=pairs[i].toString();if(v instanceof Number n)q.addProperty(k,n);else if(v instanceof Boolean b)q.addProperty(k,b);else q.addProperty(k,v.toString());}pending=UUID.randomUUID().toString();q.addProperty("token",pending);Files.writeString(dir.resolve("request-"+pending+".tmp"),q.toString());Files.move(dir.resolve("request-"+pending+".tmp"),dir.resolve("request-"+pending+".json"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);at=tick;}catch(Exception e){throw new RuntimeException(e);}}
 void delay(int ticks){waitUntil=tick+ticks;}
 void wall(String setup,double start,double end,boolean allowed){tasks.add(()->request(setup,"x",start));tasks.add(()->{check(response.get("walls").getAsInt()>0,"Boundary active "+setup);delay(25);});tasks.add(()->{wantedX=end;walkTicks=18;});tasks.add(()->{delay(10);});tasks.add(()->request("facts"));tasks.add(()->{double actual=response.get("x").getAsDouble();check(allowed?Math.abs(actual-end)<.3:setup.equals("wall_overlap")?actual<9:start<12?actual<12:actual>12,"Remote wall "+setup+" "+start+" -> "+end+" acceptedX="+actual);});}
 void reach(String label,double scale,double distance,boolean titan,boolean enrage){tasks.add(()->request("reach","scale",scale,"distance",distance,"label",label));if(titan||enrage){tasks.removeLast();tasks.add(()->{var args=new ArrayList<Object>(List.of("scale",scale,"distance",distance));if(titan){args.add("titan");args.add(true);}if(enrage){args.add("enrage");args.add(true);}request("reach",args.toArray());});}tasks.add(()->delay(30));tasks.add(()->request("facts"));tasks.add(()->{lines.add("METRIC "+label+" "+response);double expectedScale=scale*(titan?1.25:1)*(enrage?1.24:1);check(Math.abs(response.get("scale").getAsDouble()-expectedScale)<.03,"Actual size "+label);check(Math.abs(response.get("range").getAsDouble()-response.get("expectedRange").getAsDouble())<.03,"Range formula "+label);check(response.get("nativeWithin").getAsBoolean(),"Native attack validation "+label);check(Math.abs(response.get("blockRange").getAsDouble()-4.5)<.01,"Block reach unchanged "+label);request("prepare_attack");});tasks.add(()->{var mc=Minecraft.getInstance();var target=mc.level.getEntity(response.get("target").getAsInt());mc.player.connection.send(new net.bettercombat.network.Packets.C2S_AttackRequest(0,false,mc.player.getInventory().getSelectedSlot(),target,List.of(target)));delay(8);});tasks.add(()->request("facts"));tasks.add(()->check(response.get("health").getAsDouble()<996,"Real Better Combat packet damages "+label));}
 public RemoteClientProbe(){NeoForge.EVENT_BUS.addListener(this::run);tasks.add(()->request("init"));tasks.add(()->delay(35));wall("wall_outsider",11.4,13.2,false);wall("wall_outside",13.2,11.4,false);wall("wall_party",11.4,13.2,true);wall("wall_leave",11.4,13.2,false);wall("wall_join",11.4,13.2,true);wall("wall_kick",11.4,13.2,false);wall("wall_join",11.4,13.2,true);wall("wall_disband",11.4,13.2,false);wall("wall_outsider",11.8,13.2,false);wall("wall_overlap",8.4,10.2,false);
  tasks.add(()->request("wall_end","x",11.4));tasks.add(()->delay(20));tasks.add(()->{wantedX=13.2;walkTicks=18;});tasks.add(()->request("facts"));tasks.add(()->check(response.get("x").getAsDouble()>13,"Wall cleanup permits crossing"));
  reach("ordinary",1,2.6,false,false);reach("Titan",1,3.5,true,false);reach("Enrage",1,3.4,false,true);reach("Titan+Enrage",1,4.1,true,true);reach("large",2.5,7,false,false);reach("very large",4,10,false,false);reach("shrunk",.75,2,false,false);reach("removed",1,2.6,false,false);tasks.add(()->request("finish"));tasks.add(this::finish);
 }
 void finish(){if(done)return;done=true;var mc=Minecraft.getInstance();try{Files.write(mc.gameDirectory.toPath().resolve("remote-checks.txt"),lines);Files.writeString(mc.gameDirectory.toPath().resolve("remote-result.txt"),lines.stream().anyMatch(s->s.startsWith("FAIL"))?"FAIL":"PASS");}catch(Exception ignored){}mc.stop();}
 void run(ClientTickEvent.Post e){if(done)return;tick++;var mc=Minecraft.getInstance();try{
  if(mc.player==null||mc.level==null){if(tick>5000){lines.add("FAIL connection timeout");finish();}return;}mc.setScreenAndShow(null);
  if(pending!=null){if(tick-at>600)throw new AssertionError("Response timeout");var file=dir.resolve("response-"+pending+".json");if(!Files.exists(file))return;var r=JsonParser.parseString(Files.readString(file)).getAsJsonObject();if(!pending.equals(r.get("token").getAsString()))return;if(r.has("error"))throw new AssertionError(r.get("error"));response=r;pending=null;}
  if(tick<waitUntil)return;
  if(walkTicks>0){double step=(wantedX-mc.player.getX())/walkTicks--;mc.player.setPos(mc.player.getX()+step,mc.player.getY(),0);mc.player.connection.send(new ServerboundMovePlayerPacket.Pos(mc.player.position(),true,false));return;}
  if(index<tasks.size())tasks.get(index++).run();else finish();
 }catch(Throwable ex){ex.printStackTrace();lines.add("FAIL "+ex);finish();}}
}
